"""`mac system` — generated by tools/gen_groups.py from local-mac's system__* handlers. Do not edit."""
from mac.groups._backend import call


def register(registry):
    @registry.verb("system", "sleep_now", mode="write",
                   desc='put Mac to sleep immediately')
    def system_sleep_now(ns):
        return call('system', 'sleep_now')

    def system_sleep_in_args(p):
        p.add_argument('minutes', type=int)

    @registry.verb("system", "sleep_in", mode="write",
                   desc='schedule sleep after N minutes', args=system_sleep_in_args)
    def system_sleep_in(ns):
        return call('system', 'sleep_in', minutes=ns.minutes)

    @registry.verb("system", "sleep_cancel", mode="write",
                   desc='cancel scheduled sleep')
    def system_sleep_cancel(ns):
        return call('system', 'sleep_cancel')

    @registry.verb("system", "sleep_status", mode="read",
                   desc='check scheduled sleep status')
    def system_sleep_status(ns):
        return call('system', 'sleep_status')

    def system_sleep_winddown_args(p):
        p.add_argument('--minutes', default=30, type=int)

    @registry.verb("system", "sleep_winddown", mode="write",
                   desc='start wind-down routine before sleep', args=system_sleep_winddown_args)
    def system_sleep_winddown(ns):
        return call('system', 'sleep_winddown', minutes=ns.minutes)

    def system_notify_args(p):
        p.add_argument('title')
        p.add_argument('--body', default='')
        p.add_argument('--subtitle', default='')

    @registry.verb("system", "notify", mode="write",
                   desc='send a macOS notification', args=system_notify_args)
    def system_notify(ns):
        return call('system', 'notify', title=ns.title, body=ns.body, subtitle=ns.subtitle)

    @registry.verb("system", "clipboard_read", mode="read",
                   desc='read the macOS clipboard')
    def system_clipboard_read(ns):
        return call('system', 'clipboard_read')

    def system_clipboard_write_args(p):
        p.add_argument('text')

    @registry.verb("system", "clipboard_write", mode="write",
                   desc='write text to the macOS clipboard', args=system_clipboard_write_args)
    def system_clipboard_write(ns):
        return call('system', 'clipboard_write', text=ns.text)

    def system_process_list_args(p):
        p.add_argument('--name', default='')

    @registry.verb("system", "process_list", mode="read",
                   desc='list running processes, optionally filtered by name', args=system_process_list_args)
    def system_process_list(ns):
        return call('system', 'process_list', name=ns.name)

    def system_process_kill_args(p):
        p.add_argument('pid', type=int)
        p.add_argument('--force', action="store_true")

    @registry.verb("system", "process_kill", mode="write",
                   desc='kill a process by PID', args=system_process_kill_args)
    def system_process_kill(ns):
        return call('system', 'process_kill', pid=ns.pid, force=ns.force)

    def system_spotlight_search_args(p):
        p.add_argument('query')
        p.add_argument('--path', default='')

    @registry.verb("system", "spotlight_search", mode="read",
                   desc='search files with Spotlight (mdfind)', args=system_spotlight_search_args)
    def system_spotlight_search(ns):
        return call('system', 'spotlight_search', query=ns.query, path=ns.path)

    def system_icloud_list_args(p):
        p.add_argument('--path', default='')

    @registry.verb("system", "icloud_list", mode="read",
                   desc='list iCloud Drive contents at a given subpath', args=system_icloud_list_args)
    def system_icloud_list(ns):
        return call('system', 'icloud_list', path=ns.path)

    def system_foundation_models_query_args(p):
        p.add_argument('prompt')
        p.add_argument('--system', default=None)
        p.add_argument('--max-tokens', default=256, type=int)

    @registry.verb("system", "foundation_models_query", mode="read",
                   desc='query Apple Foundation Models (on-device LLM, macOS 26+) with a prompt', args=system_foundation_models_query_args)
    def system_foundation_models_query(ns):
        return call('system', 'foundation_models_query', prompt=ns.prompt, system=ns.system, max_tokens=ns.max_tokens)

    @registry.verb("system", "battery_status", mode="read",
                   desc='get Mac battery status — charge percent, charging state, health, max capacity, and cycle count')
    def system_battery_status(ns):
        return call('system', 'battery_status')

    @registry.verb("system", "cpu_status", mode="read",
                   desc='get Mac CPU status — load averages (1m/5m/15m), logical core count, and top processes by CPU usage')
    def system_cpu_status(ns):
        return call('system', 'cpu_status')

    @registry.verb("system", "memory_status", mode="read",
                   desc='get Mac memory status — total/used/free GB, wired, compressed, swap usage, used percent, and pressure level')
    def system_memory_status(ns):
        return call('system', 'memory_status')
